				fmt.Sprintf("items[%d].product_id: unknown product", i))
			return
		}
		total += p.PriceCents * int64(it.Quantity)
	}
	o := s.orders.Create(Order{UserID: req.UserID, Items: req.Items, TotalCents: total, Status: orderPending})
